payload.arguments:
{"command":"$project = 'E:\harness_project'
$destRoot = Join-Path $project 'docs\chat-logs'
$sessionDest = Join-Path $destRoot 'sessions'
$archivedDest = Join-Path $destRoot 'archived_sessions'
New-Item -ItemType Directory -Force -Path $sessionDest, $archivedDest | Out-Null
$sessionsRoot = Join-Path $env:USERPROFILE '.codex\sessions'
$archivedRoot = Join-Path $env:USERPROFILE '.codex\archived_sessions'
$sessionMatches = @()
$archivedMatches = @()
if (Test-Path $sessionsRoot) {
  $sessionMatches = Get-ChildItem $sessionsRoot -Recurse -File -Filter '*.jsonl' | Where-Object { Select-String -LiteralPath $_.FullName -Pattern 'harness_project' -Quiet -SimpleMatch }
}
if (Test-Path $archivedRoot) {
  $archivedMatches = Get-ChildItem $archivedRoot -Recurse -File -Filter '*.jsonl' | Where-Object { Select-String -LiteralPath $_.FullName -Pattern 'harness_project' -Quiet -SimpleMatch }
}
foreach ($file in $sessionMatches) {
  Copy-Item -LiteralPath $file.FullName -Destination (Join-Path $sessionDest $file.Name) -Force
}
foreach ($file in $archivedMatches) {
  Copy-Item -LiteralPath $file.FullName -Destination (Join-Path $archivedDest $file.Name) -Force
}
$manifest = @()
$manifest += $sessionMatches | ForEach-Object { [PSCustomObject]@{ collection = 'sessions'; file = $_.Name; source = $_.FullName; last_write_time = $_.LastWriteTime.ToString('s'); bytes = $_.Length } }
$manifest += $archivedMatches | ForEach-Object { [PSCustomObject]@{ collection = 'archived_sessions'; file = $_.Name; source = $_.FullName; last_write_time = $_.LastWriteTime.ToString('s'); bytes = $_.Length } }
$manifest | Sort-Object last_write_time -Descending | Export-Csv -NoTypeInformation -Encoding UTF8 -Path (Join-Path $destRoot 'manifest.csv')
[PSCustomObject]@{ sessions_copied = $sessionMatches.Count; archived_copied = $archivedMatches.Count; destination = $destRoot } | Format-List","workdir":"E:\harness_project","timeout_ms":60000}
